export const metadata = {
  title: 'Blog - My Blog',
  description: 'All blog posts'
};

export default async function BlogIndex() {
  // Use fetch with cache control for ISR equivalent
  const posts = await fetch('https://jsonplaceholder.typicode.com/posts', {
    next: { revalidate: 60 } // ISR with 60 second revalidation
  }).then(res => res.json());

  return (
    <div>
      <h1>All Blog Posts</h1>

      <div className="posts-grid">
        {posts.map((post: any) => (
          <div key={post.id} className="post-card">
            <h2>
              <a href={`/blog/${post.id}`}>{post.title}</a>
            </h2>
            <p>{post.body.substring(0, 100)}...</p>
            <form action={`/blog/${post.id}`}>
              <button type="submit">
                Read More
              </button>
            </form>
          </div>
        ))}
      </div>
    </div>
  );
}

import { notFound } from 'next/navigation';

type Post = {
  id: number;
  title: string;
  body: string;
};

type Comment = {
  id: number;
  name: string;
  body: string;
  email: string;
};

export async function generateMetadata({ params }: { params: { id: string } }) {
  try {
    const post: Post = await fetch(`https://jsonplaceholder.typicode.com/posts/${params.id}`, {
      next: { revalidate: 300 }
    }).then(res => res.json());

    return {
      title: `${post.title} - My Blog`,
      description: post.body.substring(0, 160),
      openGraph: {
        title: post.title,
        description: post.body.substring(0, 160)
      }
    };
  } catch (error) {
    return {
      title: 'Post Not Found',
      description: 'The post you are looking for does not exist'
    };
  }
}

export default async function BlogPost({ params }: { params: { id: string } }) {
  try {
    // Use Promise.all for parallel fetching (equivalent to the original)
    const [post, comments] = await Promise.all([
      fetch(`https://jsonplaceholder.typicode.com/posts/${params.id}`, {
        next: { revalidate: 300 } // 5 minutes
      }).then(res => res.json()),
      fetch(`https://jsonplaceholder.typicode.com/posts/${params.id}/comments`, {
        next: { revalidate: 300 }
      }).then(res => res.json())
    ]);

    return (
      <article>
        <form action="/">
          <button type="submit">← Back</button>
        </form>

        <h1>{post.title}</h1>
        <p>{post.body}</p>

        <h2>Comments ({comments.length})</h2>
        <div className="comments">
          {comments.map((comment: Comment) => (
            <div key={comment.id} className="comment">
              <h3>{comment.name}</h3>
              <p>{comment.body}</p>
              <small>By: {comment.email}</small>
            </div>
          ))}
        </div>
      </article>
    );
  } catch (error) {
    notFound(); // App Router equivalent of notFound: true
  }
}

export default function NotFound() {
  return (
    <div className="error-page">
      <h1>404 - Page Not Found</h1>
      <p>The page you&apos;re looking for doesn&apos;t exist.</p>
      <form action="/">
        <button type="submit">
          Go Back Home
        </button>
      </form>
    </div>
  );
}

'use client';

import { useEffect } from 'react';

type ErrorProps = {
  error: Error;
  reset: () => void;
};

export default function Error({ error, reset }: ErrorProps) {
  useEffect(() => {
    // Log the error to an error reporting service
    console.error(error);
  }, [error]);

  return (
    <div className="error-page">
      <h1>
        An error occurred on client
      </h1>
      <p>
        Sorry, something went wrong.
      </p>
      <button
        onClick={
          // Attempt to recover by trying to re-render the segment
          () => reset()
        }
      >
        Try again
      </button>
    </div>
  );
}

export async function GET() {
  // Simulate fetching posts
  const posts = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' }
  ];

  return Response.json(posts);
}

export async function POST(request: Request) {
  const { title, content } = await request.json();

  if (!title || !content) {
    return Response.json(
      { error: 'Title and content are required' },
      { status: 400 }
    );
  }

  // Simulate creating a post
  const newPost = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString()
  };

  return Response.json(newPost, { status: 201 });
}

export async function GET(request: Request, { params }: { params: { id: string } }) {
  // Simulate fetching a single post
  const post = {
    id: parseInt(params.id),
    title: `Post ${params.id}`,
    content: `This is the content for post ${params.id}`,
    createdAt: new Date().toISOString()
  };

  return Response.json(post);
}

export async function PUT(request: Request, { params }: { params: { id: string } }) {
  const { title, content } = await request.json();

  // Simulate updating a post
  const updatedPost = {
    id: parseInt(params.id),
    title: title || `Post ${params.id}`,
    content: content || `Updated content for post ${params.id}`,
    updatedAt: new Date().toISOString()
  };

  return Response.json(updatedPost);
}

export async function DELETE(request: Request, { params }: { params: { id: string } }) {
  // Simulate deleting a post
  return Response.json({ message: `Post ${params.id} deleted successfully` });
}

